SELECT lower(hex(span_id)) AS span FROM tqd_cat.spans AS s WHERE start_ns >= 1790000000000000000 AND start_ns < 1790000060000000000 AND intDiv(start_ns, 300000000000) BETWEEN 5966666 AND 5966666 AND ((multiIf(dynamicType(attrs.`success`) != 'None', coalesce(attrs.`success`.:Bool = true, false), multiIf(has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE dynamicType(attrs.`success`) != 'None'), resource_id), has((SELECT groupArray(resource_id) FROM tqd_cat.resources WHERE coalesce(attrs.`success`.:Bool = true, false)), resource_id), multiIf(arrayExists(x -> dynamicType(x) != 'None', events.attrs.`success`), arrayExists(x -> x = true, events.attrs.`success`.:Int64), multiIf(arrayExists(x -> dynamicType(x) != 'None', links.attrs.`success`), arrayExists(x -> x = true, links.attrs.`success`.:Int64), multiIf(dynamicType(scope_attrs.`success`) != 'None', coalesce(scope_attrs.`success`.:Bool = true, false), false))))))) ORDER BY span FORMAT TSV
SETTINGS final = 1, json_type_escape_dots_in_keys = 1, max_recursive_cte_evaluation_depth = 10001
